import os,re,json,collections,hashlib,sys
from html.parser import HTMLParser
base=os.path.dirname(__file__)
root=sys.argv[1]
prov=json.load(open(base+'/evidence/source-provenance.json'))
approved={x['path']:x['sha'] for x in prov['matched_sources']}
edges={}
def read(path):
 b=open(root+'/'+path,'rb').read()
 assert hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()==approved[path],path
 return b.decode('utf-8')
for p in approved:
 if not p.endswith(('.mjs','.js','.ts')) or p.endswith(('supabase-client.mjs','-vendor.mjs')):continue
 content=read(p)
 nodes=[]
 for n,line in enumerate(content.splitlines(),1):
  for kind,pattern in [('static',r"""^\s*(?:import|export)\s+(?:(?:[^'";]*?)\s+from\s*)?['"]([^'"]+)['"]"""),('dynamic',r"""import\(\s*['"]([^'"]+)['"]\s*\)""")]:
   for m in re.finditer(pattern,line):
    rel=m.group(1).split('?')[0].split('#')[0]
    if not rel.startswith('.'):continue
    dest=os.path.normpath(os.path.join(os.path.dirname(p),rel))
    if dest in approved:nodes.append({'target':dest,'line':n,'kind':kind})
 edges[p]=nodes
def trace(start,target,allow_dynamic=False):
 q=collections.deque([(start,[])])
 seen=set()
 while q:
  node,path=q.popleft()
  if node==target:return path
  if node in seen:continue
  seen.add(node)
  for e in edges.get(node,[]):
   if allow_dynamic or e['kind']=='static':q.append((e['target'],path+[{'from':node,**e}]))
 return None
